<?php require __DIR__.'/../src/App.php'; $u=requireLogin(); $c=db(); $r=queryParams($c,'SELECT p.id,p.name,p.description,pm.role FROM projects p JOIN project_members pm ON pm.project_id=p.id WHERE pm.user_id=$1 ORDER BY p.id',[(string)$u['id']]);$projects=pg_fetch_all($r)?:[];pageStart('Tổng quan');?><div class="grid"><section class="panel"><h2>Dự án của tôi</h2><p><?=count($projects)?> dự án được cấp quyền</p></section><section class="panel"><h2>Theo dõi lỗi</h2><p>Ghi nhận, phân công, kiểm thử lại và lưu lịch sử.</p><a class="btn" href="/issues.php">Mở danh sách lỗi</a></section><section class="panel"><h2>Kế hoạch phát hành</h2><p>Kiểm tra điều kiện, chốt snapshot và xuất ghi chú.</p><a class="btn" href="/releases.php">Mở phiên bản</a></section></div><section class="panel"><h2>Dự án được phân công</h2><div class="table-wrap"><table><thead><tr><th>Dự án</th><th>Mô tả</th><th>Vai trò</th><th></th></tr></thead><tbody><?php foreach($projects as $p):?><tr><td><?=h($p['name'])?></td><td><?=h($p['description'])?></td><td><span class="pill"><?=h($p['role'])?></span></td><td><a href="/issues.php?project_id=<?=(int)$p['id']?>">Xem công việc</a></td></tr><?php endforeach;?></tbody></table></div></section><p class="muted">Dữ liệu demo: 2 dự án, 40 công việc/lỗi, 15 quan hệ phụ thuộc và 3 phiên bản dự kiến (sau khi chạy seed.sql).</p><?php pageEnd(); ?>